description:
A raw pointer cannot tell whether its object still exists. Game engines often hand out **handles** instead: an index into a table plus a **generation** number. When a slot is freed its generation goes up, so an old handle to it no longer matches and is recognised as dangling.

```cpp
struct Handle { int index; unsigned generation; };

class Pool
{
public:
    Handle create(int value);
    bool destroy(Handle h);
    int* get(Handle h);
    int alive() const;
};
```

- **create** stores the value and returns its handle. It reuses the **lowest-numbered** free slot if there is one; otherwise it adds a new slot at the end. A new slot starts at generation 0.
- **destroy** frees the slot if the handle is valid, adds 1 to that slot's generation and returns true. For an invalid handle (out of range, slot already free, or wrong generation) it does nothing and returns false.
- **get** returns a pointer to the stored value for a valid handle, or `nullptr` for an invalid one.
- **alive** counts the slots in use.

A handle `{ index, generation }` is valid when `index` is inside the table, that slot is in use, and its generation equals the handle's.

starter.solution.cpp:
#include <vector>

struct Handle { int index; unsigned generation; };

class Pool
{
public:
    Handle create(int value) { return { 0, 0 }; }
    bool destroy(Handle h) { return false; }
    int* get(Handle h) { return nullptr; }
    int alive() const { return 0; }
};

solution.solution.cpp:
#include <vector>

struct Handle { int index; unsigned generation; };

class Pool
{
public:
    Handle create(int value)
    {
        for (int i{ 0 }; i < static_cast<int>(slots.size()); ++i)
        {
            if (!slots[i].used)
            {
                slots[i].used = true;
                slots[i].value = value;
                return { i, slots[i].generation };
            }
        }
        slots.push_back({ value, 0, true });
        return { static_cast<int>(slots.size()) - 1, 0 };
    }

    bool destroy(Handle h)
    {
        Slot* s{ find(h) };
        if (!s) return false;
        s->used = false;
        ++s->generation;
        return true;
    }

    int* get(Handle h)
    {
        Slot* s{ find(h) };
        return s ? &s->value : nullptr;
    }

    int alive() const
    {
        int n{ 0 };
        for (const Slot& s : slots) if (s.used) ++n;
        return n;
    }

private:
    struct Slot { int value; unsigned generation; bool used; };
    std::vector<Slot> slots;

    Slot* find(Handle h)
    {
        if (h.index < 0 || h.index >= static_cast<int>(slots.size())) return nullptr;
        Slot& s{ slots[h.index] };
        if (!s.used || s.generation != h.generation) return nullptr;
        return &s;
    }
};

unitTests:
TEST("create and get") {
    Pool pool;
    Handle a{ pool.create(10) }, b{ pool.create(20) };
    CHECK_EQ(a.index, 0); CHECK_EQ(b.index, 1);
    CHECK(pool.get(a) != nullptr); CHECK_EQ(*pool.get(a), 10);
    CHECK_EQ(*pool.get(b), 20);
    *pool.get(a) = 11;
    CHECK_EQ(*pool.get(a), 11);
    CHECK_EQ(pool.alive(), 2);
}
TEST("a destroyed handle dangles and is caught") {
    Pool pool;
    Handle a{ pool.create(10) };
    CHECK(pool.destroy(a));
    CHECK(pool.get(a) == nullptr);
    CHECK(!pool.destroy(a));
    CHECK_EQ(pool.alive(), 0);
}
TEST("a reused slot does not answer to the old handle") {
    Pool pool;
    Handle a{ pool.create(10) };
    pool.create(20);
    pool.destroy(a);
    Handle c{ pool.create(30) };
    CHECK_EQ(c.index, 0);
    CHECK_EQ(c.generation, 1u);
    CHECK(pool.get(a) == nullptr);
    CHECK_EQ(*pool.get(c), 30);
}
TEST("lowest free slot first, and bad handles") {
    Pool pool;
    Handle h0{ pool.create(0) }, h1{ pool.create(1) }, h2{ pool.create(2) };
    pool.destroy(h2); pool.destroy(h1);
    CHECK_EQ(pool.create(5).index, 1);
    CHECK_EQ(pool.create(6).index, 2);
    CHECK_EQ(pool.create(7).index, 3);
    CHECK(pool.get(Handle{ 99, 0 }) == nullptr);
    CHECK(pool.get(Handle{ -1, 0 }) == nullptr);
    CHECK(pool.get(Handle{ 0, 5 }) == nullptr);
    CHECK_EQ(*pool.get(h0), 0);
    CHECK_EQ(pool.alive(), 4);
}

